// Aplana el maestro-detalle de Symphony y clasifica cada fila.
// A diferencia de la versión Sheets, NO filtramos 'ya cargados' aquí:
// eso ahora lo garantiza Postgres con ON CONFLICT en los 3 nodos de upsert.
const rows = $('Leer hoja Compras').all().map(i => i.json);
const NIT_PROPIO = '900570024';
const num = v => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const parseFecha = v => {
  if (v === null || v === undefined || String(v).trim() === '') return null;
  if (v instanceof Date) return v.toISOString().slice(0, 10);
  if (typeof v === 'number') { // serial de Excel
    const ms = Math.round((v - 25569) * 86400 * 1000);
    return new Date(ms).toISOString().slice(0, 10);
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/); // ISO
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/); // DD/MM/YYYY (formato Symphony/Colombia)
  if (m) { const dd = m[1].padStart(2, '0'), mm = m[2].padStart(2, '0'); return `${m[3]}-${mm}-${dd}`; }
  return null; // no bloquear la carga por una fecha rara: queda null y se revisa a mano
};
const det = []; const provLoc = {};
let idActual = null; let lineasPorId = {};
const cabRaw = {};
for (const r of rows) {
  const tieneId = r.Id !== null && r.Id !== undefined && String(r.Id).trim() !== '';
  if (tieneId) { idActual = parseInt(r.Id); cabRaw[idActual] = r; }
  if (!idActual) continue;
  const esFilaProducto = r.Productos !== null && r.Productos !== undefined && String(r.Productos).trim() !== '' && String(r.Productos).trim() !== 'nan';
  if (!esFilaProducto && !tieneId) continue; // descarta solo filas vacías (ej. Retefuente sin producto)
  if (!lineasPorId[idActual]) lineasPorId[idActual] = [];
  lineasPorId[idActual].push(r);
  const nit = r.Proveedor ? String(parseInt(r.Proveedor)) : '';
  det.push({
    destino: 'DETALLE', id_compra: String(idActual),
    cod_producto: r.Productos !== null && r.Productos !== undefined ? String(r.Productos) : '',
    producto: r.NombreProd || '', info: String(r.Informacion || '').slice(0, 40),
    cantidad: num(r.Cantidad), costo_total: Math.round(num(r['Costo Total']) * 100) / 100,
    venta_total: Math.round(num(r['Venta Total']) * 100) / 100, nit_proveedor: nit,
    tipo_proveedor: nit === '' ? 'SIN_NIT' : (nit === NIT_PROPIO ? 'IMPORTADO' : 'LOCAL'),
    retencion_desc: r['Retenciones Descripcion'] || ''
  });
  if (nit && nit !== NIT_PROPIO) {
    const k = idActual + '|' + nit;
    provLoc[k] = (provLoc[k] || 0) + num(r['Costo Total']);
  }
}
const outCab = Object.entries(cabRaw).map(([id, r]) => {
  const nits = new Set((lineasPorId[id] || []).map(l => l.Proveedor ? String(parseInt(l.Proveedor)) : '').filter(Boolean));
  const tipo = nits.size === 0 ? 'SIN_NIT' : (nits.size === 1 && nits.has(NIT_PROPIO) ? 'IMPORTADO' : (nits.has(NIT_PROPIO) ? 'MIXTO' : 'LOCAL'));
  return { json: {
    destino: 'CABECERA', id_compra: String(id), fecha: parseFecha(r['Fecha de Creación']),
    cliente: r.Nombre || '', documento: r.Documento || '', centro_costo: r['Centro de Costo'] || '',
    vendedor: r.Vendedor || '', estado_symphony: r.Estado || '', gestion: r.Gestion || '',
    valor_venta: Math.round(num(r.ValorVenta) * 100) / 100, valor_domicilio_cobrado: num(r['Valor domicilio']),
    costo_transporte_symphony: num(r['Costo domicilio']), tipo_origen: tipo,
    total_compra: num(r['Total Compra']), transportista_symphony: r.Trasnportista || '',
    origen: r.Origen || '', destino_geo: r.Destino || ''
  } };
});
const outDet = det.map(d => ({ json: d }));
const outProv = Object.entries(provLoc).map(([k, v]) => {
  const [id, nit] = k.split('|');
  return { json: { destino: 'PROV_LOCAL', id_compra: id, nit_proveedor: nit, valor_costo: Math.round(v * 100) / 100 } };
});
return [...outCab, ...outDet, ...outProv];

